<h1>بررسی تجربه</h1><p>نسخه <?= $this->h($version['version_no']) ?> · <?= $this->h($version['status']) ?></p><div class="grid2"><article class="card"><h2>نسخه قبل <?= $this->h($previous['version_no']??'') ?></h2><h3><?= $this->h($previous['title']??'نسخه قبلی ندارد') ?></h3><p class="prose"><?= nl2br($this->h($previous['body']??'')) ?></p></article><article class="card"><h2>نسخه مورد بررسی</h2><h3><?= $this->h($version['title']) ?></h3><p class="prose"><?= nl2br($this->h($version['body'])) ?></p></article></div><section class="card section"><p>یادداشت بررسی قبلی: <?= $this->h($version['review_note']) ?></p><?= $this->start('/experience/review') ?><input type="hidden" name="id" value="<?= $this->h($version['id']) ?>"><label>تصمیم<select name="decision"><option value="approved">تأیید و انتشار این نسخه</option><option value="changes">درخواست اصلاح در نسخه جدید</option><option value="rejected">رد</option></select></label><label for="review-note">دلیل یا درخواست اصلاح</label><textarea id="review-note" name="note" rows="5"><?= $this->val('note') ?></textarea><button>ثبت تصمیم</button></form></section><section class="card section"><?= $this->start('/experience/unpublish') ?><input type="hidden" name="id" value="<?= $this->h($version['experience_id']) ?>"><button class="secondary">توقف انتشار تجربه</button></form></section>
